/* ============================================================================
   JOE's Addons for ABMC — wiki 批量推送脚本（浏览器控制台版）
   ----------------------------------------------------------------------------
   用法：
     1. 在浏览器里登录你的 wiki；
     2. 随便打开 wiki 上的一个页面（保证是同源）；
     3. 按 F12 打开开发者工具 → Console（控制台）；
     4. 把本文件**全部内容**复制粘贴进去 → 回车；
        （Chrome 首次会要求你手动输入 allow pasting 才允许粘贴）
     5. 脚本会逐页创建/更新，并在控制台打印进度表。

   说明：
     * 用的是你浏览器**当前的登录会话**与 CSRF token，不会把任何凭证发到别处；
     * 默认会把编辑标记为 bot（不出现在最近更改里）；想留痕就把 bot 改成 0；
     * 想先试跑不写入：把下面的 DRY_RUN 改成 true，只会打印"将要做什么"；
     * 若你的 wiki 不是 Miraheze 标准路径（/w/api.php），改下面的 API 变量。
   ============================================================================ */
(async () => {
  const DRY_RUN = false;          // true = 只预览，不写入
  const BOT     = 1;              // 1 = 标记为机器人编辑；0 = 普通编辑
  const API     = "/w/api.php";   // 你的 wiki 的 API 路径
  const SUMMARY = "从本地 wikitext 批量导入/更新（JOE's Addons for ABMC wiki）";
  const PAYLOAD = "";

  const log = (...a) => console.log("%c[wiki-push]", "color:#2b8a3e;font-weight:bold", ...a);

  // ---- 1) 解压内嵌数据 ----------------------------------------------------
  const bin = Uint8Array.from(atob(PAYLOAD), c => c.charCodeAt(0));
  const pages = JSON.parse(await new Response(
      new Blob([bin]).stream().pipeThrough(new DecompressionStream("gzip"))
  ).text());
  log(`待处理页面：${pages.length} 个`);

  const q = async (params) => {
    const body = new URLSearchParams({ format: "json", formatversion: "2", ...params });
    const res = await fetch(API, { method: "POST", body, credentials: "same-origin" });
    const data = await res.json();
    if (data.error) throw new Error(`${data.error.code}: ${data.error.info}`);
    return data;
  };

  // ---- 2) 先确认登录状态 + 拿 CSRF token ---------------------------------
  const who = await q({ action: "query", meta: "userinfo" });
  const user = who.query?.userinfo?.name;
  if (!user) { console.error("没有登录：请先登录 wiki 再运行本脚本。"); return; }
  log(`当前登录用户：${user}`);
  let token = (await q({ action: "query", meta: "tokens", type: "csrf" })).query.tokens.csrf;

  // ---- 3) 逐页写入 --------------------------------------------------------
  const results = [];
  for (let i = 0; i < pages.length; i++) {
    const { title, text } = pages[i];
    const no = String(i + 1).padStart(2, " ");
    if (DRY_RUN) {
      log(`[${no}/${pages.length}] (预览) ${title} — ${text.length} 字符`);
      results.push({ 序号: i + 1, 标题: title, 结果: "预览" });
      continue;
    }
    try {
      const data = await q({
        action: "edit", title, text, summary: SUMMARY,
        token, bot: BOT, watchlist: "nochange", minor: 0,
        recreate: 1, assert: "user"
      });
      const r = data.edit;
      const ok = r.result === "Success";
      log(`[${no}/${pages.length}] ${ok ? "✅" : "⚠️"} ${title} — ${r.result}（rev ${r.newrevid ?? "-"}）`);
      results.push({ 序号: i + 1, 标题: title, 结果: r.result, 修订: r.newrevid ?? "" });
    } catch (e) {
      log(`[${no}/${pages.length}] ❌ ${title} — ${e.message}`);
      results.push({ 序号: i + 1, 标题: title, 结果: "失败：" + e.message });
      if (/badtoken|notoken/i.test(e.message)) {   // token 过期就重取一次
        token = (await q({ action: "query", meta: "tokens", type: "csrf" })).query.tokens.csrf;
      }
    }
    await new Promise(r => setTimeout(r, 120));    // 温柔一点，别触发限流
  }

  console.table(results);
  const okCount = results.filter(r => r.结果 === "Success").length;
  log(`完成：成功 ${okCount} / ${results.length}${DRY_RUN ? "（预览模式，未写入）" : ""}`);
  log("建议接着看一眼 Special:RecentChanges 与分类页 Category:生物 / Category:权杖。");
})();
